// EU VAT & Tax Calculator
const rates = { DE: 0.19, AT: 0.20, FR: 0.20, IT: 0.22, ES: 0.21, NL: 0.21 };
const rate = rates[inputs.country_code] || 0.19;
const net = Number(inputs.amount);
const vat = Math.round(net * rate * 100) / 100;
bb[inputs.output_field || 'tax_calculation'] = {
  net: net,
  vat_rate: rate,
  vat_amount: vat,
  gross: Math.round((net + vat) * 100) / 100
};
trigger('done');

// String Formatter
let val = String(inputs.text || '');
switch (inputs.operation) {
  case 'uppercase': val = val.toUpperCase(); break;
  case 'lowercase': val = val.toLowerCase(); break;
  case 'trim': val = val.trim(); break;
  case 'slugify': val = val.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, ''); break;
}
bb[inputs.output_field || 'formatted_text'] = val;
trigger('done');

// JSON Required Fields Validator
const obj = typeof inputs.target_object === 'object' ? inputs.target_object : {};
const keys = String(inputs.required_keys || '').split(',').map(s => s.trim()).filter(Boolean);
const missing = [];
for (const k of keys) {
  if (obj[k] === undefined || obj[k] === null || obj[k] === '') {
    missing.push(k);
  }
}
const valid = missing.length === 0;
bb[inputs.output_field || 'validation'] = {
  valid: valid,
  missing: missing
};
trigger(valid ? 'done' : 'invalid');
